
import type { CheckoutRecoveryEmailSettings } from './CheckoutRecoveryEmailSettings.js';
import type { CheckoutSavedPaymentDetailsSettings } from './CheckoutSavedPaymentDetailsSettings.js';

export type CheckoutSettings = { /** An exact hostname such as pay.example.com. Omission keeps the current hostname. Null removes it and starts the redirect window. minLength: 1. maxLength: 253. */ "custom_domain"?: string | null; /** Default delivery methods for checkout creation requests that omit delivery_method_ids, payment links without delivery_method_ids, and invoice checkouts. The default applies only when the order has items to deliver; otherwise no methods are assigned. Methods and their dependencies must be active when saved. Send [] to clear this default; null is rejected. Each checkout pins its assigned methods when created. An explicit empty delivery_method_ids array on a checkout creation request overrides this default. */ "default_delivery_method_ids"?: Array<string>; /** Default lifetime in seconds for generic checkout sessions. Invoice checkout sessions instead use the fixed deadline of the active invoice public-link generation. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 60. maximum: 86400. */ "default_expires_in_seconds"?: string; "enabled_payment_options"?: Array<string>; /** Merchant default for hosted checkout promotion code entry. Object-level promotion_config.codes_enabled can override it for a session or payment link. */ "promotion_code_entry_enabled"?: boolean; /** Checkout reminder email: one email to a buyer who entered an email address in hosted checkout and left without paying. Merchant scope only. Effective settings default it to off with a 3600 second delay. */ "recovery_email"?: CheckoutRecoveryEmailSettings; "require_billing_address"?: boolean; "require_email"?: boolean; "require_phone"?: boolean; /** Whether hosted checkout offers buyers the option to save the card they type for faster checkout at this merchant. Merchant scope only. Effective settings default it to on. */ "saved_payment_details"?: CheckoutSavedPaymentDetailsSettings; };
